apiVersion: apps/v1
kind: Deployment
metadata: { name: shipments-api }
spec:
  replicas: 3
  selector: { matchLabels: { app: shipments-api } }
  strategy: { rollingUpdate: { maxSurge: 1, maxUnavailable: 0 } }
  template:
    metadata: { labels: { app: shipments-api } }
    spec:
      containers:
      - name: api
        image: 123456789.dkr.ecr.eu-west-1.amazonaws.com/shipments-api:1.8.3
        ports: [{ containerPort: 8080 }]
        resources: { requests: { cpu: 250m, memory: 256Mi }, limits: { memory: 512Mi } }
        readinessProbe: { httpGet: { path: /health/ready, port: 8080 } }
        livenessProbe:  { httpGet: { path: /health/live,  port: 8080 } }
        securityContext: { runAsNonRoot: true, readOnlyRootFilesystem: true }

