o.Events = new JwtBearerEvents
{
    OnTokenValidated = async ctx =>
    {
        var jti = ctx.Principal!.FindFirst("jti")?.Value;
        var cache = ctx.HttpContext.RequestServices.GetRequiredService<IConnectionMultiplexer>().GetDatabase();
        if (jti is null || await cache.KeyExistsAsync($"revoked:{jti}")) ctx.Fail("Token revoked");
    }
};

