public override async ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData e, InterceptionResult<int> r, CancellationToken ct = default)
{
    foreach (var entry in e.Context!.ChangeTracker.Entries().Where(x => x.State is EntityState.Added or EntityState.Modified or EntityState.Deleted))
        e.Context.Add(AuditRecord.From(entry, _user.Id, _clock.GetUtcNow(), _correlation.Id));
    return await base.SavingChangesAsync(e, r, ct);
}
